    /** Mobile. */
    on_double_click(handler: (event: PointEvent, cx: Context) => void): this;
    /** Mobile. */
    on_long_press(handler: (event: PointEvent, cx: Context) => void): this;
    /** Mobile. */
    on_press_in(handler: (event: PointEvent, cx: Context) => void): this;
    /** Mobile. */
    on_press_out(handler: (event: PointEvent, cx: Context) => void): this;
    /** Mobile. */
    on_pan(handler: (event: PanEvent, cx: Context) => void): this;
    /** Mobile. */
    on_pinch(handler: (event: PinchEvent, cx: Context) => void): this;
    /** Mobile: on a scroll view (`overflow_*_scroll`). */
