    selected(value?: boolean): this;
    pressed(value?: boolean): this;
    aria_selected(value?: boolean): this;
    role(name: Role): this;
    accessibility_label(description: string): this;
    /** Mobile. */
    accessibility_hint(hint: string): this;
    /** Mobile. */
    accessibility_value(value: string): this;
    /** Mobile. */
    accessibility_hidden(hidden?: boolean): this;
    /** Mobile: finds the element from native UI tests. */
    test_id(id: string): this;
    /** Mobile: extends the touch target, in points (all sides, or `[top, right, bottom, left]`). */
