    tab_index(index: number): this;
    tab_stop(value: boolean): this;
    aria_level(level: number): this;
    aria_active_descendant(): this;
    window_control_area(area: "drag" | "close" | "max" | "min"): this;
    content_focus_handle(handle: FocusHandle): this;
    with_item_to_measure_index(index: number): this;
