  export function writeFile(path: string, data: string | Uint8Array): Promise<void>;
  export function readdir(path: string): Promise<string[]>;
  export function exists(path: string): Promise<boolean>;
  export function unlink(path: string): Promise<void>;
  export function mkdir(path: string, options?: { recursive?: boolean }): Promise<void>;
  export function stat(path: string): Promise<{ size: number; is_file: boolean; is_dir: boolean; modified: number }>;
  export function rename(from: string, to: string): Promise<void>;
  const fs: {
    readFile: typeof readFile; writeFile: typeof writeFile; readdir: typeof readdir; exists: typeof exists;
    unlink: typeof unlink; mkdir: typeof mkdir; stat: typeof stat; rename: typeof rename;
  };
