type NativeShellWindow = import("native-shell").Window;
interface Window extends NativeShellWindow {}
declare var window: Window & typeof globalThis;
declare const localStorage: import("native-shell").Storage;
declare const sessionStorage: import("native-shell").Storage;

declare function setTimeout(handler: (...args: any[]) => void, ms?: number, ...args: any[]): number;
declare function setInterval(handler: (...args: any[]) => void, ms?: number, ...args: any[]): number;
declare function clearTimeout(id: number | undefined): void;
